package main
import("flag";"fmt";"io";"net/http";"sort";"sync";"time")
type sample struct{lat int64; code int}
func main(){base:=flag.String("base","http://localhost:18080","");token:=flag.String("token","","");vus:=flag.Int("vus",10,"");iters:=flag.Int("iterations",20,"");flag.Parse();var mu sync.Mutex; all:=[]sample{};var wg sync.WaitGroup;start:=time.Now();for v:=0;v<*vus;v++{wg.Add(1);go func(v int){defer wg.Done();c:=&http.Client{Timeout:15*time.Second};for i:=0;i<*iters;i++{body:=fmt.Sprintf(`{"name":"bench-%d-%d","rewardType":"gift","value":0,"repeatable":true,"confirmationMethod":"staff","branchIds":[]}`,v,i);t:=time.Now();req,_:=http.NewRequest(http.MethodPost,*base+"/api/v1/reward-definitions",io.NopCloser(&stringReader{s:body}));req.Header.Set("Authorization","Bearer "+*token);req.Header.Set("Content-Type","application/json");resp,e:=c.Do(req);code:=599;if e==nil{code=resp.StatusCode;io.Copy(io.Discard,resp.Body);resp.Body.Close()};mu.Lock();all=append(all,sample{time.Since(t).Microseconds(),code});mu.Unlock()}}(v)};wg.Wait();sort.Slice(all,func(i,j int)bool{return all[i].lat<all[j].lat});pct:=func(p int)int64{return all[(len(all)-1)*p/100].lat/1000};err:=0;for _,s:=range all{if s.code<200||s.code>=300{err++}};fmt.Printf("vus=%d requests=%d rps=%.2f p50_ms=%d p95_ms=%d p99_ms=%d max_ms=%d errors=%d\n",*vus,len(all),float64(len(all))/time.Since(start).Seconds(),pct(50),pct(95),pct(99),all[len(all)-1].lat/1000,err)}
type stringReader struct{s string;i int};func(r *stringReader)Read(p []byte)(int,error){if r.i>=len(r.s){return 0,io.EOF};n:=copy(p,r.s[r.i:]);r.i+=n;return n,nil}
